    def getCryptoData(self):
        cryptoList = pd.read_csv('D:\\PhD\\Metropolis\\cryptoList.txt')
        ticker = cryptoList['Ticker']
        P_all = np.ones([7, 1])
        tmp = defaultdict(lambda: None)

        for ix, data in enumerate(ticker):
            ixStr = str(ix)
            tmp[ixStr] = pd.read_csv('D:\\PhD\\Metropolis\\RealData9\\' + data, header=None)
            mask = np.isnan(tmp[ixStr][1])
            tmp[ixStr][1][mask] = np.interp(np.flatnonzero(mask), np.flatnonzero(~mask), tmp[ixStr][1][~mask])
            if not ix:
                commonDates = tmp[ixStr][0]
            commonDates = np.intersect1d(commonDates, tmp[ixStr][0])

            if np.std(tmp[ixStr][tmp[ixStr][0].isin(commonDates)][1]) == 0:
                break


        P_all.resize((7, len(commonDates)), refcheck=False)
        for ix in range(len(ticker)):
            ixStr = str(ix)
            P_all[ix, :] = tmp[ixStr][tmp[ixStr][0].isin(commonDates)][1]

        return P_all